// 全ポイ活アプリ管理画面（mock-admin）
// アプリモック（mock-app）と同じ localStorage の状態を読み書きする。管理画面の変更はアプリ側に即時反映される。
// 各画面に「spec」（poikatsu-spec admin/ に既存の運用機能）／「新規」（現行仕様にない運用機能）／「外部再現」（NACS 等の外部イベントの再現）を表示する。
import {KEY,TODAY,yen,pt,offersOf,surveys,initialState,day,L,applyReservations,visibleSlots,visibleOffers,challengeSlots,challengeAchieved,total,autoReview,manualReview,reviewPending,exchangeConditions,validateSlot,publishSlot,removeSlot,POINT_KEYS,reservePointSetting,deleteReservation,setMissionReward,setMissionEnabled,setSurveyRate,setExchangeCap,activeScreenSetting,saveScreenSetting,deleteScreenSetting,progressOffer,rejectOffer,audit,surveyReward,missionTasks,featurePublication,saveFeature,removeFeature,slotLink,CHINCHIRO_ROLES,ensureChinchiro,chinchiroStatus,setChinchiro} from './model.js';
const root=document.querySelector('#root'),modal=document.querySelector('#modal');
const scopeParams=new URLSearchParams(location.search);const scopeKey=scopeParams.get('configScope');const storageKey=scopeKey?'poikatsu-operation:'+scopeKey:KEY;

let state;function load(){try{if(scopeKey&&!localStorage.getItem(storageKey)){localStorage.setItem(storageKey,localStorage.getItem(KEY)||JSON.stringify(initialState()));}const s=JSON.parse(localStorage.getItem(storageKey));state=s&&s.version===9?s:initialState();}catch{state=initialState();}applyReservations(state);const needsBundleSample=!(state.nacs?.intake?.sampleVersion>=1);ensureBundleSample(state);if(needsBundleSample)localStorage.setItem(storageKey,JSON.stringify(state));normalizeBannerRecords(state);}
load();
if(ensureHighRewardDemo(state))localStorage.setItem(storageKey,JSON.stringify(state));
let slotFilter='all',screenCode='tametoku_quick',editingSlot=null,editingSetting=null,editingFeature=null,editingCampaignBanner=null,formError='',toastTimer;
const esc=t=>String(t??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const route=()=>({slots:'banners',features:'campaigns','text-ads':'banners'})[location.hash.slice(1)]||location.hash.slice(1).split('/')[0]||'dashboard';
const save=()=>localStorage.setItem(storageKey,JSON.stringify(state));
const toast=t=>{const el=document.querySelector('#toast');el.textContent=t;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3200);};
const badge=(kind,text)=>`<span class="badge ${kind}">${text||({spec:'spec',new:'新規',ext:'外部再現'})[kind]}</span>`;
const kindName={banner:'バナー（最上部）',ad:'カテゴリ広告（架空サービス）',campaign:'キャンペーン（ブースト）',recommend:'おすすめ',challenge:'チャレンジボーナス',ticker:'テキストバナー',notice:'告知'};
const tabName={daily:'ホーム：デイリーミッション',steps:'ホーム：歩く',challenge:'ホーム：チャレンジボーナス',game:'ホーム：ゲーム',shopping:'ホーム：買い物',survey:'ホーム：アンケート',credit:'ホーム：クレカ',high:'お得：ガポガポ',quick:'お得：すぐできる'};
const placementName={'daily-middle':'ホーム枠 → デイリーミッション中部（320×50）',top:'ホーム最上部バナー（home_first）',category:'カテゴリ広告枠（ホーム各タブ／お得：ガポガポ・すぐできる）',carousel:'ホーム特集枠',feed:'おすすめ枠',popup:'起動時ポップアップ',interstitial:'タブ切り替え時インステ広告',pill:'お得 テキストバナー',challenge:'チャレンジ枠',sub:'サブ枠'};
const segmentName={all:'全員',new:'新規',regular:'継続',finance:'金融未利用'};
const destName=id=>offersOf(state).find(o=>o.id===id)?.name||({survey:'アンケート',wallet:'ポイント・交換'})[id]||id;
const slotStatus=s=>!s.enabled?['off','停止中']:s.start>state.date?['warn','予約中']:s.end<state.date?['off','期間終了']:['on','配信中'];

// ===== 共通 =====
 function shell(title,content){const items=[['dashboard','ダッシュボード',''],['sec','運用'],['top-menu','TOP画面上部のメニュー',''],['missions','デイリーミッション設定',''],['challenges','チャレンジボーナス',''],['banners','バナー&テキスト広告',''],['tametoku-order','お得タブ表示設定','new'],['quick-links','お得タブサービス名リンク','new'],['campaigns','キャンペーンページ',''],['receipts','レシート掲載管理',''],['receipt-options','レシート販促オプション',''],['games','ミニゲーム'],['chinchiro','チンチロ','new'],['planned','追加予定'],['sec','報酬・判定'],['points','付与設定（歩数・動画）','spec'],['survey','アンケート還元率','spec'],['review','審査・交換上限','spec'],['sec','確認'],['screens','案件グループ設定','spec'],['cases','成果・解禁（NACS 再現）','ext'],['metrics','実績','new'],['logs','変更ログ','']];const r=route();
 return `<div class="layout"><aside class="side"><div class="brand"><i>P</i>全ポイ活アプリ管理画面</div><nav><button type="button" class="feature-overview-button" data-feature-overview>アプリ別機能ON-OFF</button>${items.map(([k,l,b])=>k==='sec'?`<div class="sec">${l}</div>`:k==='games'?`<div id="planned-operation-nav"></div><div class="sec" >ミニゲーム </div>`:k==='planned'?'<div id="planned-nav"></div>':`<a href="#${k}" style="" class="${r===k?'current':''}">${l}${b?badge(b):''}</a>`).join('')}</nav><div class="foot">凡例：${badge('spec')} poikatsu-spec の admin/ に既存<br>${badge('new')} 現行仕様にない新規機能<br>${badge('ext')} 外部連携（NACS）の再現<br><br><a href="../mock-app/" target="_blank">アプリモックを開く ↗</a><br><a href="../mock-nacs/" target="_blank">NACS モックを開く ↗</a><br>同じブラウザーなら変更が即時反映されます。</div></aside><div><header class="topbar"><h1>${title}</h1><span class="meta">運用者：デモ運用者（管理者ロール）</span><label>確認日 <input type="date" id="admin-date" value="${state.date}"></label><button class="btn sm" data-action="reload">アプリの状態を再読み込み</button></header><main>${content}</main></div></div>`;}

// ===== ダッシュボード =====
function dashboard(){const pend=state.user.pendings;const act=visibleSlots(state);const t=missionTasks(state);const chin=(()=>{try{ensureChinchiro(state);return chinchiroStatus(state);}catch{return null;}})();return `<div class="cards">
<div class="card"><h3>アプリ構成（現行モック）</h3><b>下部 4 タブ</b><p class="tiny">ホーム ・ お得 ・ 簡単 ・ マイページ</p><p class="tiny" style="margin-top:6px"><b>お得</b>のサブタブ：おすすめ／ガポガポ／すぐできる／マイ案件<br><b>簡単</b>＝アンケート主軸<br><b>マイページ</b>＝マイ案件・友達招待・交換</p></div>
<div class="card"><h3>目減りゼロ表示</h3><b>${state.showNoLoss!==false?'ON':'OFF'}</b><p class="tiny">ホーム残高・マイページの比較表示</p><p style="margin-top:8px"><button class="btn sm" data-action="toggle-noloss">${state.showNoLoss!==false?'表示をOFF':'表示をON'}</button></p></div>
<div class="card"><h3>チンチロ</h3><b>${chin&&chin.visible?`残り ${chin.remaining}/${chin.dailyLimit}`:'停止／非表示'}</b><p class="tiny">3つ一致：大当たり ／ 2つ一致：当たり</p><p class="tiny" style="margin-top:6px"><a href="#chinchiro">チンチロ設定へ</a></p></div>
<div class="card"><div class="k">配信中の運用枠</div><div class="v">${act.length}<small>/ ${state.slots.length}</small></div><div class="s">${act.filter(x=>x.kind==='challenge').length}件のチャレンジ開催中</div></div>
<div class="card"><div class="k">審査待ち（付与予定）</div><div class="v">${pend.length}<small>件</small></div><div class="s">自動判定 ${pend.filter(x=>x.review==='auto').length}／有人審査 ${pend.filter(x=>x.review==='manual').length}</div></div>
<div class="card"><div class="k">デモ利用者の合算ポイント</div><div class="v">${pt(total(state))}<small>pt</small></div><div class="s">交換可能 ${pt(state.user.approved)}／準備中 ${pt(state.user.pending)}</div></div>
<div class="card"><div class="k">本日のミッション進捗</div><div class="v">${t.done}<small>/ ${t.total}</small></div><div class="s">受け取り可能 ${t.claimable}件</div></div>
<div class="card"><div class="k">日次交換総額</div><div class="v">${Math.round(state.exchangeUsedToday/L(state).exchangeDailyCap*100)}<small>%</small></div><div class="s">${pt(state.exchangeUsedToday)} / ${pt(L(state).exchangeDailyCap)} pt</div></div>
</div>
<div class="two"><section class="panel"><h2>本日の配信内容</h2><div class="tbl"><table><thead><tr><th>枠</th><th>種別</th><th>表示位置</th><th>期間</th></tr></thead><tbody>${act.map(s=>`<tr><td><a href="#${s.kind==='challenge'?'challenges':s.placements.includes('pill')?'banners/offers/text':'banners'}">${esc(s.name)}</a></td><td>${kindName[s.kind]}</td><td>${s.placements.map(p=>placementName[p]||p).join('・')}</td><td>${s.start.slice(5)}〜${s.end.slice(5)}</td></tr>`).join('')||'<tr><td colspan="4" class="tiny">配信中の枠はありません</td></tr>'}</tbody></table></div></section>
<section class="panel"><h2>最近の変更</h2><div class="tbl"><table><thead><tr><th>日時</th><th>操作</th></tr></thead><tbody>${state.logs.slice(0,8).map(l=>`<tr><td class="tiny">${l.at.slice(0,16).replace('T',' ')}</td><td>${esc(l.label)}</td></tr>`).join('')||'<tr><td colspan="2" class="tiny">変更はまだありません</td></tr>'}</tbody></table></div><p class="tiny" style="margin-top:8px"><a href="#logs">変更ログをすべて見る</a></p></section></div>
<section class="panel"><h2>このモックの位置づけ</h2><p class="desc">ユーザー向けアプリのモック（mock-app）を実現するための運用画面。アプリは下部 4 タブ（ホーム／お得／簡単／マイページ）。お得内はおすすめ／ガポガポ／すぐできる／マイ案件。チンチロ・目減りゼロはダッシュボードと各設定画面から操作。既存の運用機能（poikatsu-spec の admin/）と新規運用機能を同じ画面群で扱う。案件そのもの（登録・報酬・掲出順・成果の承認）は <a href="../mock-nacs/" target="_blank">NACS モック</a> が持ち、この管理画面は「どの画面にどのグループを出すか」と「成果をポイントに換える」側だけを扱う。既存機能との差分は次段階のドキュメントで整理する。</p></section>`;}

// ===== 運用枠 =====
const slotSection=()=>route()==='challenges'?'challenge':['#text-ads','#banners/offers/text'].includes(location.hash)?'text':'banner';
const slotPageTitle=()=>({challenge:'チャレンジボーナス',text:'オトク内テキスト広告',banner:'バナー&テキスト広告'})[slotSection()];
const belongsToSection=(s,section)=>section==='challenge'?s.kind==='challenge':section==='text'?s.kind==='ticker'||s.placements.includes('pill'):s.kind!=='ticker'&&!s.placements.includes('pill')&&(s.kind!=='challenge'||s.placements.some(p=>p!=='challenge'));
function slotForm(v){if(slotSection()==='banner')return carouselForm(state,v,location.hash.slice(1).split('/').slice(1));const section=slotSection(),o=v||{id:'slot-'+crypto.randomUUID().slice(0,8),name:'',kind:section==='challenge'?'challenge':section==='text'?'ticker':'banner',destination:'travel',placements:section==='challenge'?['challenge']:section==='text'?['pill']:['top'],enabled:true,start:state.date,end:state.date.slice(0,8)+'30',segment:'all',priority:50,title:'',text:'',rewardMode:'flat',reward:0,to:'',challengeGoal:1000,participants:0,bonus:100};
const input=(label,name,value,type='text')=>`<label>${label}<input type="${type}" name="${name}" value="${esc(value??'')}" required></label>`;
return `<form class="grid" id="slot-form" data-id="${o.id}" data-section="${section}">${input('管理名（必須）','name',o.name)}<input type="hidden" name="kind" value="${o.kind}">${section==='banner'?`<label class="wide">リンク先の案件・特集ページ（URL）<input name="to" value="${esc(deepLinkUrl(o.to||'offer/'+o.destination,location.href))}" placeholder="コピーしたディープリンクを貼り付け" required></label>`:section==='text'?'':`<label>リンク先の案件<select name="destination">${offersOf(state).map(x=>`<option value="${x.id}" ${x.id===o.destination?'selected':''}>${esc(x.name)}</option>`).join('')}${['survey','wallet'].includes(o.destination)?`<option value="${o.destination}" selected>${destName(o.destination)}</option>`:''}</select></label>`}${input('表示開始日','start',o.start,'date')}${input('表示終了日','end',o.end,'date')}${input('優先度（0〜100）','priority',o.priority,'number')}<label>公開状態<select name="enabled"><option value="1" ${o.enabled?'selected':''}>公開</option><option value="0" ${!o.enabled?'selected':''}>停止</option></select></label><label>対象者<select name="segment">${Object.entries(segmentName).map(([k,n])=>`<option value="${k}" ${o.segment===k?'selected':''}>${n}</option>`).join('')}</select></label>
${section==='banner'?`${o.placements.includes('challenge')?'<input type="hidden" name="placements" value="challenge">':''}<div class="wide"><h3>配信先</h3><div class="checks">${Object.entries(placementName).filter(([k])=>!['pill','challenge'].includes(k)).map(([k,n])=>`<label><input type="checkbox" name="placements" value="${k}" ${o.placements.includes(k)?'checked':''}>${n}</label>`).join('')}</div></div><label>カテゴリ広告のタブ<select name="tab"><option value="">指定なし</option>${Object.entries(tabName).map(([k,n])=>`<option value="${k}" ${o.tab===k?'selected':''}>${n}</option>`).join('')}</select></label><label>カテゴリ広告の位置<select name="position"><option value="top" ${o.position!=='bottom'?'selected':''}>上部</option><option value="bottom" ${o.position==='bottom'?'selected':''}>下部</option></select></label>${uploadField(o)}`:o.placements.map(p=>`<input type="hidden" name="placements" value="${p}">`).join('')}
${section==='text'?`<label class="wide">広告テキスト<textarea name="title" maxlength="120" required>${esc(o.title)}</textarea></label><p class="tiny wide">オトクの検索窓の下に表示するテキスト広告です。</p>`:''}
${section==='challenge'?`${input('目標人数','challengeGoal',o.challengeGoal,'number')}${input('現在の参加人数（デモ）','participants',o.participants,'number')}${input('達成ボーナス（pt）','bonus',o.bonus,'number')}`:section==='banner'?'':`<label class="wide">リンク先（案件・特集・チャレンジボーナス）<input name="to" value="${esc(o.to||'offer/'+o.destination)}" list="deeplinks" required><datalist id="deeplinks"><option value="challenges">チャレンジボーナス一覧</option>${(state.features||[]).map(f=>`<option value="feature/${f.id}">${esc(f.title)}</option>`).join('')}${offersOf(state).map(x=>`<option value="offer/${x.id}">${esc(x.name)}</option>`).join('')}</datalist></label>`}
<div class="actions"><button class="btn primary" type="submit">${v?'更新して反映':'追加して反映'}</button><button class="btn" type="button" data-action="cancel-slot">閉じる</button><span class="err" role="alert">${esc(formError)}</span></div></form>`;}
function campaignBanners(){return `<section class="panel"><h2>キャンペーンページ内のバナー</h2><p class="desc">ページ上部の画像もここでまとめて差し替えます。掲載案件は「キャンペーンページ」で編集します。</p>${editingCampaignBanner?(()=>{const f=state.features.find(x=>x.id===editingCampaignBanner);return f?`<form id="campaign-banner-form" class="grid" data-id="${f.id}"><h3 class="wide">${esc(f.title)}</h3>${uploadField(f)}<div class="actions"><button class="btn primary">画像を保存</button><button type="button" class="btn" data-action="close-campaign-banner">閉じる</button><span class="err" role="alert"></span></div></form>`:'';})():''}<div class="tbl"><table><thead><tr><th>キャンペーン</th><th>画像</th><th>操作</th></tr></thead><tbody>${(state.features||[]).map(f=>`<tr><td>${esc(f.title)}</td><td>${f.bannerImage?'登録済み':'未登録'}</td><td><button class="btn" data-action="edit-campaign-banner" data-id="${f.id}">バナーを編集</button> <a href="../mock-app/#feature/${f.id}" target="_blank">アプリで確認</a></td></tr>`).join('')}</tbody></table></div></section>`;}
function challengeOrderPage(){const list=challengeOrder(state);return `<section class="panel"><h3>共通アイコン</h3><form id="challenge-icon-form">${iconUpload(state.challengeIcon||'')}<button class="btn primary">アイコンを保存</button></form></section><section class="panel"><h2>チャレンジボーナスの並び順</h2><p class="desc">上にある案件からアプリに表示します。案件詳細・開催期間・目標人数・ボーナスはNACSで編集します。</p><p><a href="../mock-nacs/#challenges" target="_blank">NACSでチャレンジボーナスを編集 ↗</a></p><table><thead><tr><th>表示順</th><th>案件</th><th>期間</th><th>ボーナス</th><th>並び替え</th></tr></thead><tbody>${list.map((c,i)=>`<tr><td>${i+1}</td><td>${esc(destName(c.destination))}</td><td>${esc(c.start)}〜${esc(c.end)}</td><td>${pt(c.bonus)}pt</td><td><button class="btn" data-action="move-challenge" data-id="${c.id}" data-dir="-1" ${i===0?'disabled':''}>上へ</button> <button class="btn" data-action="move-challenge" data-id="${c.id}" data-dir="1" ${i===list.length-1?'disabled':''}>下へ</button></td></tr>`).join('')}</tbody></table></section>`;}
const frameTitle=(frame,position)=>position==='top'?'デイリーミッション · 上部':bannerFrames[frame].positions[position].replace(/・?320×\d+|・?300×\d+|（320×100）/g,'').replace(/[（）]/g,'').replace(/・$/,'').replace('広告枠','広告');
function bannerFramesPage(){
 const rows=Object.entries(bannerFrames).flatMap(([frame,group])=>Object.keys(group.positions).map(position=>({group:group.label,name:frameTitle(frame,position),size:sizeLabel(slotBannerSize(framePlacement(frame,position))),href:`#banners/${frame}/${position}`,slots:state.slots.filter(s=>belongsToSection(s,'banner')&&frameOf(s)[0]===frame&&frameOf(s)[1]===position)})));
 rows.push({group:'オトク枠',name:'オトク · 検索窓下',size:'テキスト',href:'#banners/offers/text',slots:state.slots.filter(s=>belongsToSection(s,'text'))});
 const groups=[...new Set(rows.map(r=>r.group))];
 return `<div class="banner-workspace banner-console"><div class="banner-heading"><div><h2>配信枠</h2><p>掲載場所と登録状況を確認し、広告を管理します。</p></div><span class="banner-note">${rows.length}枠</span></div><section class="banner-table-panel"><div class="banner-filters"><label>配信枠を検索<input type="search" data-banner-search placeholder="掲載場所・サイズで検索"></label><label>掲載画面<select data-banner-group><option value="">すべての画面</option>${groups.map(g=>`<option>${esc(g)}</option>`).join('')}</select></label><span data-banner-count>${rows.length}件</span></div><div class="tbl"><table class="banner-table"><thead><tr><th>配信枠名</th><th>掲載画面</th><th>サイズ・形式</th><th class="num">登録数</th><th>公開設定・期間</th><th>操作</th></tr></thead><tbody>${rows.map(r=>{const active=r.slots.filter(s=>slotStatus(s)[0]==='on').length,reserved=r.slots.filter(s=>slotStatus(s)[0]==='warn').length;return `<tr data-banner-row data-group="${esc(r.group)}" data-search="${esc(r.name+' '+r.group+' '+r.size)}"><td><a class="banner-name" href="${r.href}">${esc(r.name)}</a></td><td>${esc(r.group)}</td><td><span class="banner-format">${esc(r.size)}</span></td><td class="num">${r.slots.length}</td><td><span class="banner-state ${active?'is-active':''}">${active?'期間内 '+active+'件':reserved?'予約 '+reserved+'件':r.slots.length?'停止・期間終了':'未登録'}</span></td><td><a class="banner-manage" href="${r.href}">管理する →</a></td></tr>`;}).join('')}<tr data-banner-no-results hidden><td colspan="6" class="banner-empty">条件に一致する配信枠はありません。</td></tr></tbody></table></div><div class="banner-table-footer">公開設定と掲載期間をもとに表示しています。実際の配信には画像・リンク先などの条件も適用されます。</div></section><section class="banner-table-panel banner-related"><h3>その他の掲載設定</h3><a href="#banners/side"><strong>ホーム・お得のサイドタブ</strong><span>画像・文言・リンク先</span><b>設定する →</b></a><a href="#banners/features"><strong>キャンペーンページ上部</strong><span>320×100px</span><b>画像を管理 →</b></a></section></div>`;
}
function filterBannerFrames(){const container=document.querySelector('.banner-console');if(!container)return;const query=container.querySelector('[data-banner-search]').value.trim().toLowerCase(),group=container.querySelector('[data-banner-group]').value;let count=0;container.querySelectorAll('[data-banner-row]').forEach(row=>{row.hidden=!!((group&&row.dataset.group!==group)||!row.dataset.search.toLowerCase().includes(query));if(!row.hidden)count++;});container.querySelector('[data-banner-count]').textContent=count+'件';container.querySelector('[data-banner-no-results]').hidden=count!==0;}
document.addEventListener('input',e=>{if(e.target.matches('[data-banner-search]'))filterBannerFrames();});
document.addEventListener('change',e=>{if(e.target.matches('[data-banner-group]'))filterBannerFrames();});
function bannerFramePage(frame,position){const text=position==='text';const list=state.slots.filter(s=>text?belongsToSection(s,'text'):belongsToSection(s,'banner')&&frameOf(s)[0]===frame&&frameOf(s)[1]===position).sort((a,b)=>(a.displayOrder??999999)-(b.displayOrder??999999));return `<div class="banner-workspace"><nav class="banner-breadcrumb"><a href="#banners">バナー&テキスト広告</a><span>／</span><span>${esc(bannerFrames[frame].label)}</span></nav><div class="banner-heading"><div><h2>${text?'オトク · 検索窓下':esc(frameTitle(frame,position))}</h2><p>${text?'検索窓の下に表示する広告文とリンク先を設定します。':['popup','interstitial'].includes(position)?'300×250pxのバナーを1回につき1枚表示します。配信候補が複数ある場合は均等に1枚を選びます。':'左のハンドルをドラッグして表示順を変更できます。上から順に最大5枚表示し、停止・期間外のバナーは除外します。'}</p></div><span class="banner-size-chip">${text?'テキスト':sizeLabel(slotBannerSize(framePlacement(frame,position)))}</span></div>${adDeliveryForm(state,position)}${editingSlot!==null?`<section class="panel banner-edit-panel"><h3>${text?(editingSlot?'テキスト広告を編集':'テキスト広告を新規登録'):(editingSlot?'バナー設定を編集':'バナーを新規登録')}</h3>${slotForm(editingSlot||null)}</section>`:`<section class="panel banner-list-panel"><div class="banner-list-heading"><h3>${text?'登録済みテキスト広告':'登録済みバナー'} <span class="tiny">${list.length}件</span></h3><button class="btn primary" data-action="new-slot">＋ 新規登録</button></div>${list.length?`<div class="banner-records">${list.map((s,i)=>{const [k,n]=slotStatus(s);return `<article class="banner-record" data-order-id="${esc(s.id)}">${!text&&!['popup','interstitial'].includes(position)?`<button class="banner-drag" draggable="true" data-drag-banner="${esc(s.id)}" aria-label="${esc(s.name)}を並べ替え。上下矢印キーでも操作できます">⠿ <span>${i+1}</span></button>`:''}<div class="banner-record-main"><strong>${esc(s.name)}</strong><div class="banner-record-meta">${badge(k,n)}<span>${text?'テキスト':['popup','interstitial'].includes(position)?'1枚':(s.slides?.length||1)+'枚'}</span><span>${esc(s.start)} 〜 ${esc(s.end)}</span></div></div><div class="banner-record-actions"><button class="btn primary" data-action="edit-slot" data-id="${s.id}">編集</button><button class="btn" data-action="toggle-slot" data-id="${s.id}">${s.enabled?'停止':'開始'}</button><details class="banner-more"><summary class="btn" aria-label="その他の操作">⋯</summary><div><button class="btn" data-action="dup-slot" data-id="${s.id}">複製</button><button class="btn danger" data-action="del-slot" data-id="${s.id}">削除</button></div></details></div></article>`;}).join('')}</div>`:'<div class="banner-empty"><strong>まだバナーが登録されていません</strong><p>「新規登録」から広告を設定してください。</p><small>登録・公開するまで、この枠はアプリに表示されません。</small></div>'}</section>`}</div>`;}
function slotsPage(){if(route()==='challenges')return challengeOrderPage();const section=slotSection(),[frame,position]=location.hash.slice(1).split('/').slice(1);if(section==='banner'&&frame==='side')return sideTabsPage();if(section==='text')return bannerFramePage('offers','text');if(section==='banner'&&frame==='features')return `<a href="#banners">← バナー&テキスト広告の枠一覧</a>${campaignBanners()}`;if(section==='banner'&&!bannerFrames[frame]?.positions[position])return bannerFramesPage();if(section==='banner')return bannerFramePage(frame,position);const list=state.slots.filter(s=>belongsToSection(s,section)&&(section!=='banner'||(()=>{const [f,p]=frameOf(s);return f===frame&&p===position;})()));return `${section==='banner'?'<a href="#banners">← バナー&テキスト広告の枠一覧</a>':''}<section class="panel"><h2>${section==='banner'?esc(bannerFrames[frame].positions[position])+'枠':slotPageTitle()}</h2><p class="desc">${section==='banner'?'この枠に表示するバナーを登録・編集します。複数のバナーは自動でカルーセル表示されます。全件停止すると枠ごと非表示になります。':'オトクの検索窓の下にある広告枠です。広告テキスト・タップ先・掲載期間を管理します。'}</p><div class="toolbar"><span class="grow"></span><button class="btn primary" data-action="new-slot">＋ 新規作成</button></div>
${editingSlot!==null?`<div class="panel" style="background:#FAFCFB">${slotForm(editingSlot||null)}</div>`:''}
<div class="tbl"><table><thead><tr><th>管理名</th><th>種別</th><th>表示位置</th><th>リンク先</th><th>期間</th>${section==='banner'?'<th>バナー枚数</th>':'<th>対象</th><th>優先度</th>'}<th>報酬</th><th>状態</th><th>操作</th></tr></thead><tbody>${list.map(s=>{const [k,n]=slotStatus(s);return `<tr class="${k==='off'?'dim':''}"><td><b>${esc(s.name)}</b><div class="tiny">${esc(s.title).split('\n')[0]}</div></td><td>${kindName[s.kind]||s.kind}</td><td>${section==='banner'?(()=>{const [frame,position]=frameOf(s);return frame?`${bannerFrames[frame]?.label||'旧サイドタブ'} → ${bannerFrames[frame]?.positions[position]||position}`:'旧構成（編集して配信枠を選択）';})():s.placements.map(p=>placementName[p]||p).join('<br>')}</td><td>${esc(s.to?.startsWith('feature/')?(state.features||[]).find(f=>'feature/'+f.id===s.to)?.title||'特集ページ':destName(s.destination))}<div class="tiny">→ ${esc(slotLink(s))}</div></td><td class="tiny">${s.start}<br>〜${s.end}</td>${section==='banner'?`<td>${s.slides?.length||1}枚・均等配信</td>`:`<td>${segmentName[s.segment]||s.segment}</td><td class="num">${s.priority}</td>`}<td class="num">${s.kind==='challenge'?`${s.participants?.toLocaleString()}/${s.challengeGoal?.toLocaleString()}人<br>+${pt(s.bonus||0)}pt`:s.reward?(s.rewardMode==='rate'?s.reward+'%':s.rewardMode==='multiplier'?'×'+s.reward:pt(s.reward)+'pt'):'—'}</td><td>${badge(k,n)}</td><td class="ops"><button class="btn sm" data-action="edit-slot" data-id="${s.id}">編集</button> <button class="btn sm" data-action="dup-slot" data-id="${s.id}">複製</button> <button class="btn sm" data-action="toggle-slot" data-id="${s.id}">${s.enabled?'停止':'開始'}</button> <button class="btn sm danger" data-action="del-slot" data-id="${s.id}">削除</button></td></tr>`;}).join('')}</tbody></table></div></section>`;}

// ===== 特集ページ =====
function featureForm(v){const o=v||{id:'campaign-'+crypto.randomUUID().slice(0,8),title:'',start:state.date,end:'',offerIds:[],bundleTags:[]};return `<form class="grid campaign-simple-form" id="feature-form" data-new="${v?'0':'1'}"><input type="hidden" name="id" value="${esc(o.id)}"><label class="wide">管理名<input name="title" value="${esc(o.title)}" required></label><label>掲載開始日<input type="date" name="start" value="${esc(featurePublication(o).start)}"></label><label>掲載終了日<input type="date" name="end" value="${esc(featurePublication(o).end)}"></label>${uploadField(o)}${offerPicker(offersOf(state),o.offerIds,state,o.bundleTags||[])}<div class="wide"><button type="button" class="btn" data-action="preview-feature-draft">プレビュー ↗</button></div><div class="actions"><button class="btn primary" type="submit">保存</button><button class="btn" type="button" data-action="cancel-feature">キャンセル</button><span class="err" role="alert">${esc(formError)}</span></div></form>`;}

function featuresPage(){if(editingFeature!==null)return `<section class="panel"><h2>${editingFeature?'キャンペーンを編集':'キャンペーンを作成'}</h2>${featureForm(editingFeature||null)}</section>`;const list=state.features||[];const usedBy=id=>state.slots.filter(x=>x.to===`feature/${id}`).map(x=>x.name);return `<section class="panel"><h2>キャンペーンページ ${badge('new')}</h2><p class="desc">案件キュレーション・単一案件リッチLP・特集記事を作成できます。特集名・紹介文・掲載期間・掲載件数を設定し、案件名で探して選択してください。画像は「バナー&テキスト広告」で管理します。</p><div class="toolbar"><span class="grow"></span><button class="btn primary" data-action="new-feature">＋ キャンペーンを作成</button></div>${editingFeature!==null?`<div class="panel" style="background:#FAFCFB">${featureForm(editingFeature||null)}</div>`:''}<div class="tbl"><table><thead><tr><th>ID／ディープリンク</th><th>掲載する特集名</th><th>掲載期間・件数</th><th>選択した案件</th><th>使用している枠</th><th>操作</th></tr></thead><tbody>${list.map(f=>`<tr><td><code>feature/${f.id}</code></td><td><b>${esc(f.title)}</b><br><small>${{collection:'案件キュレーション',single:'単一案件リッチLP（画像入稿）',article:'特集記事'}[f.kind]||'案件キュレーション'}</small></td><td class="tiny">${esc(featurePublication(f).start||'制限なし')} 〜 ${esc(featurePublication(f).end||'制限なし')}<br>最大 ${featurePublication(f).displayLimit}件</td><td class="tiny">${f.offerIds.map(id=>esc(offersOf(state).find(o=>o.id===id)?.name||id)).join('、')}</td><td class="tiny">${usedBy(f.id).map(esc).join('<br>')||'—'}</td><td class="ops"><button class="btn sm" data-action="edit-feature" data-id="${f.id}">編集</button> <button class="btn sm danger" data-action="del-feature" data-id="${f.id}">削除</button></td></tr>`).join('')||'<tr><td colspan="6" class="tiny">特集はありません</td></tr>'}</tbody></table></div></section>`;}


// ===== チンチロ =====
function tableRows(name,table){return `<div class="tbl"><table data-table="${name}"><thead><tr><th>役 ID（固定）</th><th>表示名（固定）・条件</th><th class="num">ウェイト</th><th>報酬方式</th><th class="num">倍率</th><th class="num">固定pt</th></tr></thead><tbody>${table.map(x=>`<tr><td><code>${esc(x.id)}</code></td><td><b>${esc(x.label)}</b><div class="tiny">${CHINCHIRO_ROLES.find(r=>r.id===x.id).condition}</div></td><td class="num"><input aria-label="${x.label}のウェイト" type="number" name="${name}-weight" value="${x.weight}" min="0" step="1" style="width:80px"></td><td><select name="${name}-mode" data-ch-mode><option value="mult" ${x.pt==null?'selected':''}>倍率</option><option value="fixed" ${x.pt!=null?'selected':''}>固定pt</option></select></td><td class="num">${['none','spill','hifumi'].includes(x.id)?'<span>0</span><input type="hidden" name="'+name+'-mult" value="0">':`<input aria-label="${x.label}の倍率" type="number" name="${name}-mult" value="${x.mult}" min="0" step="0.1" style="width:80px">`}</td><td class="num">${['none','spill','hifumi'].includes(x.id)?'<span>0pt</span><input type="hidden" name="'+name+'-pt" value="0">':`<input aria-label="${x.label}の固定pt" type="number" name="${name}-pt" value="${x.pt??''}" min="0" step="1" style="width:90px" placeholder="空=倍率">`}</td></tr>`).join('')}</tbody></table></div>`;}
function chinchiroPage(){ensureChinchiro(state);const cfg=state.chinchiro;const st=chinchiroStatus(state);const sum=t=>t.reduce((a,x)=>a+x.weight,0);return `<section class="panel"><h2>チンチロ（日次抽選） ${badge('new')}</h2><p class="desc">役ごとに抽選ウェイトと報酬方式を設定します。倍率は基準ptに適用。通常の目は出目に応じた倍率が初期値です。負け役は0ptで、保有ポイントは減りません。動画で当選確率UP、当選後の動画で受け取ります。</p>
<form class="grid" id="chinchiro-form">
<label>表示<select name="enabled"><option value="1" ${cfg.enabled?'selected':''}>有効</option><option value="0" ${!cfg.enabled?'selected':''}>停止</option></select></label>
<label>1日の回数上限<input type="number" name="dailyLimit" min="0" max="20" value="${cfg.dailyLimit}"></label>
<label>初期ユーザー期間（日）<input type="number" name="earlyDays" min="0" max="90" value="${cfg.earlyDays}"></label>
<label>基準ポイント（×倍率）<input type="number" name="baseReward" min="0" max="99999" value="${cfg.baseReward}"></label>
<div class="wide"><h3>通常テーブル（ウェイト合計 ${sum(cfg.normalTable)}）</h3>${tableRows('normal',cfg.normalTable)}</div>
<div class="wide"><h3>初期テーブル（ウェイト合計 ${sum(cfg.earlyTable)}）・当たりやすめ</h3>${tableRows('early',cfg.earlyTable)}</div>
<div class="actions"><button class="btn primary" type="submit">保存してアプリに反映</button><span class="err">${esc(formError)}</span></div>
</form>
<div class="preview" style="margin-top:16px"><h4>デモ利用者のいま</h4>
<p class="tiny">右上表示：${st.visible?`残り <b>${st.remaining}</b> / ${st.dailyLimit} 回${st.early?'（初期応援モード）':''}`:'非表示（ゲスト or 停止）'}　使用済み ${st.used} 回　累計ロール ${state.user.chinchiroRolls||0} 回</p>
</div>
<div class="note">ギャンブル演出は強いが、付与はボーナスのみ。景表法・射幸心・原資は要確認。</div></section>`;}

// ===== 案件画面設定 =====
const listSelect=v=>`<select name="g-list"><option value="">（なし・ナビ用）</option>${(state.nacs?.lists||[]).map(l=>`<option value="${l.code}" ${v===l.code?'selected':''}>${l.code}</option>`).join('')}</select>`;
function menuCategoryCell(g){const current=menuCategoryOf(g);return `<td><select name="g-menu-category" aria-label="メニューカテゴリ">${Object.entries(menuCategories).map(([id,name])=>`<option value="${id}" ${current===id?'selected':''}>${name}</option>`).join('')}</select></td>`;}
function menuContentSelect(kind,selected){const options=Object.entries(menuContentOptions(state,kind));return `<select name="g-category" aria-label="表示する内容" required>${options.length?options.map(([id,name])=>`<option value="${id}" ${id===selected?'selected':''}>${esc(name)}</option>`).join(''):'<option value="">キャンペーンページを先に作成してください</option>'}</select>`;}
function settingForm(code,st){const o=st||{id:'ss-'+Date.now().toString(36),applyAt:state.date+'T00:00',memo:'',groups:[{id:'g-'+Date.now().toString(36),name:'',category:code==='home_tabs'?'daily':'すべて',icon:'gift',unit:'jpy',order:1,tags:true}]};const cats=code==='home_tabs'?['daily','steps','challenge','game','shopping','survey','credit']:['すべて','買い物','旅行','ゲーム','アプリ','金融','challenges','surveys','mycases'];const icons=['cart','plane','game','phone','yen','gift','spark','bag','survey','walk','wallet','calendar','chat'];
 return `<form class="grid ${code==='home_tabs'?'top-menu-form':''}" id="setting-form" data-code="${code}" data-id="${o.id}"><label>適用開始日時<input type="datetime-local" name="applyAt" value="${o.applyAt}"></label><label class="wide">メモ<input name="memo" value="${esc(o.memo)}"></label>
<div class="wide"><h3>${code==='home_tabs'?'表示するメニュー':'案件グループ'}</h3><div class="tbl"><table id="group-rows"><thead><tr><th>表示名（改行は \\n）</th>${code==='home_tabs'?'<th>メニューカテゴリ</th>':''}<th>表示する内容</th><th>案件一覧コード（NACS）</th><th>アイコン</th><th>表示単位</th><th>表示順</th><th>タグ表示</th><th></th></tr></thead><tbody>${o.groups.map((g,i)=>`<tr data-gid="${g.id}"><td><input name="g-name" value="${esc(g.name)}"></td>${code==='home_tabs'?menuCategoryCell(g):''}<td>${code==='home_tabs'?menuContentSelect(menuCategoryOf(g),g.category):`<select name="g-category">${cats.map(c=>`<option value="${c}" ${g.category===c?'selected':''}>${code==='home_tabs'?(tabName[c]||c).replace('ホーム：',''):c}</option>`).join('')}</select>`}</td><td>${listSelect(g.listCode)}</td><td><select name="g-icon">${icons.map(c=>`<option ${g.icon===c?'selected':''}>${c}</option>`).join('')}</select>${iconUpload(g.iconImage||'')}</td><td><select name="g-unit"><option value="jpy" ${g.unit==='jpy'?'selected':''}>円</option><option value="point" ${g.unit==='point'?'selected':''}>pt</option></select></td><td><input type="number" name="g-order" value="${g.order}" style="width:60px"></td><td><input type="checkbox" name="g-tags" ${g.tags?'checked':''}></td><td><button class="btn sm danger" type="button" data-action="del-group-row">削除</button></td></tr>`).join('')}</tbody></table></div><button class="btn sm" type="button" data-action="add-group-row">＋ メニュー／グループを追加</button></div>
<div class="actions"><button class="btn primary" type="submit">${st?'更新':'作成'}（適用開始日時が現在以前なら即時反映）</button><button class="btn" type="button" data-action="cancel-setting">閉じる</button><span class="err">${esc(formError)}</span></div></form>`;}
function topMenuPage(){screenCode='home_tabs';return screensPage();}
function screensPage(){const top=route()==='top-menu';const codes=Object.keys(state.screens);if(!state.screens[screenCode])screenCode=codes[0];const scr=state.screens[screenCode];const active=activeScreenSetting(state,screenCode);const now=state.date+'T23:59';const stateOf=x=>x.id===active?.id?['on','適用中']:x.applyAt>now?['warn','予約中']:['off','過去'];
 return `<section class="panel"><h2>${top?'TOP画面上部のメニュー':'案件グループ設定'}</h2><p class="desc">${top?'買い物・ゲーム・アンケートなど、TOP画面上部のメニューを管理します。メニューカテゴリを選び、そのカテゴリに対応する表示内容・表示名・アイコン・順序を設定し、行の追加・削除で表示するメニューを変更できます。':'オトク内の案件グループ設定を管理します。'}</p>${top?'':`<div class="tabs">${codes.filter(c=>c!=='home_tabs').map(c=>`<button data-action="screen-code" data-code="${c}">${c}</button>`).join('')}</div>`}
<p class="tiny">メモ：${esc(scr.memo)}　適用中：${active?`${active.applyAt.replace('T',' ')}（${active.groups.length}グループ）`:'なし（0 件が返る）'}</p>
<div class="toolbar"><span class="grow"></span><button class="btn primary" data-action="new-setting">＋ 設定を作成（予約可）</button></div>
${editingSetting!==null?`<div class="panel" style="background:#FAFCFB">${settingForm(screenCode,editingSetting||null)}</div>`:''}
<div class="tbl"><table><thead><tr><th>適用開始日時</th><th>状態</th><th>メモ</th><th>グループ</th><th>操作</th></tr></thead><tbody>${scr.settings.slice().sort((a,b)=>b.applyAt.localeCompare(a.applyAt)).map(x=>{const [k,n]=stateOf(x);return `<tr class="${k==='off'?'dim':''}"><td>${x.applyAt.replace('T',' ')}</td><td>${badge(k,n)}</td><td>${esc(x.memo)}</td><td class="tiny">${x.groups.slice().sort((a,b)=>a.order-b.order).map(g=>`${esc(g.name)}（${g.listCode?`<code>${g.listCode}</code>`:g.category}・${g.unit==='jpy'?'円':'pt'}）`).join('、')}</td><td class="ops"><button class="btn sm" data-action="edit-setting" data-id="${x.id}">編集</button> <button class="btn sm danger" data-action="del-setting" data-id="${x.id}">削除</button></td></tr>`;}).join('')||'<tr><td colspan="5" class="tiny">設定がありません</td></tr>'}</tbody></table></div><div class="note spec">spec：適用中の設定を削除すると直前の過去の設定に戻る。案件の並び順は NACS の掲出順で、タメルコ側で並べ替えない。案件一覧コードとその掲出順は NACS モック（<a href="../mock-nacs/#lists" target="_blank">案件一覧コード ↗</a>）で管理する。</div></section>`;}

// ===== 付与設定 =====
function pointsPage(){const rows=Object.entries(POINT_KEYS);const pending=state.reservations.filter(r=>!r.applied&&r.age==='adult');return `<section class="panel"><h2>付与設定（歩数・動画）</h2>${[{title:'報酬ポイント',unit:'pt'},{title:'動画の回数',unit:'回'},{title:'歩数条件',unit:'歩'}].map(group=>`<section style="margin:24px 0 32px"><h3>${group.title}（${group.unit}）</h3>${rows.filter(([,d])=>d.unit===group.unit).map(([k,d])=>`<form id="point-setting-${k}" data-point-key="${k}" style="padding:18px 0;border-bottom:1px solid #dce8e2"><label for="point-${k}"><b>${esc(d.label.replace('（新規）',''))}</b></label><div class="toolbar" style="margin-top:12px;align-items:end"><label>設定値（${d.unit}）<input id="point-${k}" name="value" type="number" min="${d.min}" max="${d.max}" step="1" value="${state.limits[k]}" required style="width:140px"></label><label>反映タイミング<select name="applyMode" onchange="this.form.elements.applyAt.disabled=this.value==='now';this.form.elements.applyAt.required=this.value==='scheduled';this.form.querySelector('[type=submit]').textContent=this.value==='now'?'保存':'予約'"><option value="now">即時反映</option><option value="scheduled">日時を指定</option></select></label><label>適用日時<input type="datetime-local" name="applyAt" disabled></label><button class="btn primary" type="submit">保存</button></div><span class="err" role="alert"></span></form>`).join('')}</section>`).join('')}${pending.length?`<h3>未適用の予約</h3><div class="tbl"><table><thead><tr><th>設定</th><th>値</th><th>適用日時</th><th></th></tr></thead><tbody>${pending.map(r=>`<tr><td>${esc(POINT_KEYS[r.key].label)}</td><td>${r.value}</td><td>${esc(r.applyAt)}</td><td><button class="btn sm danger" data-action="del-reservation" data-id="${r.id}">削除</button></td></tr>`).join('')}</tbody></table></div>`:''}</section>`;}

// ===== デイリーミッション報酬 =====
function missionEditorRow(m){const fixed=isFixedMission(m);return `<tr data-task-id="${m.id}" data-task-type="${m.type}"><td><b>${fixed?'基本項目':m.type==='VIEW_OFFER'?'案件詳細閲覧':'既存の追加項目'}</b></td><td><label>タイトル<input name="title" value="${esc(m.title)}" maxlength="80"  required></label><label>説明<input name="sub" value="${esc(m.sub)}" maxlength="140"  required></label>${m.type==='VIEW_OFFER'?`<label>対象案件<select name="offerId" required><option value="">案件を選択</option>${offersOf(state).map(o=>`<option value="${o.id}" ${o.id===m.offerId?'selected':''}>${esc(o.category)} ／ ${esc(o.name)}${o.active===false?'（停止中）':''}</option>`).join('')}</select></label><label>遷移先リンク<input name="to" value="${esc(m.to|| (m.offerId?'offer/'+m.offerId:''))}" placeholder="offer/travel" required></label><small>対象案件を選ぶとリンクを自動入力します。案件詳細のURLも貼り付けられます。</small>`:''}</td><td><input type="number" name="reward" value="${m.reward}" min="1" max="99999" aria-label="${esc(m.title)} 報酬" required>pt</td><td><input type="checkbox" name="enabled" ${m.enabled?'checked':''}  aria-label="${esc(m.title)} 有効"></td><td>${m.type==='VIEW_OFFER'?'<button class="btn" type="button" data-action="remove-browse-mission">削除</button>':'—'}</td></tr>`;}
function dailyGroupEditor(g){return `<fieldset data-daily-group="${g.id}" style="margin:16px 0;padding:18px;border:1px solid #dce8e2;border-radius:10px"><legend>デイリーミッション</legend><input type="hidden" name="group-name" value="共通ミッション"><div class="daily-group-missions">${g.missions.map(m=>{const video=m.id==='video'||m.id.startsWith('video-');const url=new URL('../mock-app/',location.href);url.hash=m.to||(video?'videos':'surveys');return `<div data-daily-id="${m.id}" style="border-top:1px solid #e2eae6;padding:14px 0"><label><input name="enabled" type="checkbox" ${m.enabled!==false?'checked':''}>${video?'動画':'アンケート'}を表示</label><label>タイトル<input name="title" value="${esc(m.title||(video?'動画を見る':'アンケートに回答する'))}" required maxlength="80"></label><label>説明<input name="sub" value="${esc(m.sub||(video?'動画の視聴完了でポイント獲得':'回答完了でポイント獲得'))}" maxlength="140"></label><label>遷移先ディープリンク<input name="to" value="${esc(url.href)}" required style="width:100%"></label><button type="button" class="btn sm" data-action="daily-mission-up">↑ 上へ</button><button type="button" class="btn sm" data-action="daily-mission-down">↓ 下へ</button><button type="button" class="btn sm" data-action="daily-remove-mission">削除</button></div>`;}).join('')}</div><div class="toolbar"><select name="add-source" aria-label="追加するミッション">${surveys.map(q=>`<option value="survey-${q.id}">${esc(q.title)}</option>`).join('')}</select><button type="button" class="btn" data-action="daily-add-mission">＋ ミッションを追加</button></div></fieldset>`;}
function sideTabsPage(){return `<div class="banner-workspace side-editor"><nav class="banner-breadcrumb"><a href="#banners">バナー＆テキスト広告</a><span>／</span><span>サイドタブ</span></nav><div class="banner-heading"><h2>サイドタブ</h2><span class="banner-size-chip">1タブ1広告</span></div><div class="side-editor-tabs" role="tablist" aria-label="掲載するタブ"><button type="button" role="tab" aria-selected="true" data-side-edit="home">ホーム</button><button type="button" role="tab" aria-selected="false" data-side-edit="offers">お得</button></div><form id="side-tabs-form">${['home','offers'].map(key=>{const c=sideTabConfig(state,key);return `<section data-side-key="${key}" ${key==='offers'?'hidden':''} class="side-editor-card"><div class="side-editor-fields"><label>タブの文言<input name="label" maxlength="12" value="${esc(c.label||'おすすめ')}" required placeholder="例：おすすめ"></label><span class="tiny">12文字まで</span><label style="margin-top:18px">バナー上の文言<input name="heading" maxlength="60" value="${esc(c.heading??c.label??'おすすめ')}" placeholder="例：今週のおすすめ案件"></label><div class="side-image-area"><label>遷移先スクエア画像<input type="file" data-side-image accept="image/png,image/jpeg,image/webp"></label><p class="tiny">PNG・JPEG・WebP ／ 正方形・5MBまで</p><input type="hidden" name="image" value="${esc(c.image||'')}"><p data-side-error class="err" role="alert"></p></div><label>リンク先<input name="link" value="${esc(c.link||'#offers')}" required placeholder="URLまたはアプリ内リンク"></label></div><div class="side-editor-preview"><span class="tiny">登録画像</span><img data-side-preview src="${esc(c.image||'')}" ${c.image?'':'hidden'}></div></section>`;}).join('')}<div class="side-editor-footer"><a class="btn" href="#banners">配信枠一覧へ</a><button class="btn primary" type="submit">変更を保存</button><span class="err" role="alert"></span></div></form></div><style>.side-editor-tabs{display:flex;gap:6px;margin:18px 0}.side-editor-tabs button{border:1px solid #dce7e1;background:white;color:#72857a;padding:11px 36px;border-radius:8px;cursor:pointer;font-weight:700}.side-editor-tabs [aria-selected=true]{background:#e4f3eb;border-color:#26846a;color:#167458}.side-editor-card{display:grid;grid-template-columns:minmax(0,1fr) 280px;gap:32px;background:white;border:1px solid #dce7e1;border-radius:12px;padding:24px}.side-editor-card[hidden]{display:none}.side-editor-fields label{display:block;font-size:13px;font-weight:600;color:#667c70}.side-editor-fields input:not([type=hidden]){display:block;width:100%;box-sizing:border-box;margin-top:8px;padding:12px;border:1px solid #dce7e1;border-radius:8px;color:#294638;background:white;font:inherit}.side-editor-fields .tiny{font-size:12px;color:#84948a}.side-image-area{border:1px dashed #bad0c3;border-radius:10px;padding:16px;margin:20px 0 16px;background:#f8fbf9}.side-editor-preview{padding:14px;background:#f5f8f6;border-radius:10px;align-self:start}.side-editor-preview img{display:block;width:100%;aspect-ratio:1;object-fit:contain;margin-top:12px}.side-editor-preview img[hidden]{display:none}.side-editor-footer{display:flex;align-items:center;gap:12px;margin-top:20px}.side-editor-footer .primary{margin-left:auto}@media(max-width:900px){.side-editor-card{grid-template-columns:1fr}.side-editor-preview{max-width:280px}}</style>`;}
document.addEventListener('click',e=>{const tab=e.target.closest('[data-side-edit]');if(!tab)return;document.querySelectorAll('[data-side-edit]').forEach(b=>b.setAttribute('aria-selected',String(b===tab)));document.querySelectorAll('[data-side-key]').forEach(p=>p.hidden=p.dataset.sideKey!==tab.dataset.sideEdit);});

document.addEventListener('change',async e=>{if(!e.target.matches('[data-side-image]'))return;const box=e.target.closest('[data-side-key]'),file=e.target.files[0],error=box.querySelector('[data-side-error]');error.textContent='';if(!file)return;try{if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>5*1024*1024)throw Error('PNG・JPEG・WebP、5MB以内の画像を選んでください。');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});const im=new Image();await new Promise((resolve,reject)=>{im.onload=resolve;im.onerror=()=>reject(Error('画像を読み込めません。'));im.src=data;});if(im.width!==im.height)throw Error('正方形の画像を選んでください。');box.querySelector('[name=image]').value=data;const preview=box.querySelector('[data-side-preview]');preview.src=data;preview.hidden=false;}catch(err){error.textContent=err.message;}});
function quickLinkDestinationFields(item){const detailOptions=offersOf(state).map(o=>`<option value="${esc(o.id)}" ${item.destinationType==='offer-detail'&&item.destination===o.id?'selected':''}>${esc(o.name)}</option>`).join('');return `<select name="destinationType" aria-label="${esc(item.label)} 遷移種別">${QUICK_LINK_DESTINATIONS.map(([value,label])=>`<option value="${value}" ${item.destinationType===value?'selected':''}>${label}</option>`).join('')}</select><input name="destination" value="${esc(item.destination||'')}" placeholder="一覧: バンドル属性名 ／ 詳細: 案件ID ／ URL: https://..."><small class="tiny">一覧は任意のバンドル属性名、詳細は案件ID、URLは https:// または http://</small>`;}
function tametokuOrderPage(){return sectionOrderEditor(state);}
function quickLinksPage(){return `<section class="panel quick-links-admin"><h2>お得タブのサービス名リンク ${badge('new')}</h2><p class="desc">サービス名リンクは、管理画面でサービス名・サービスアイコン画像・リンク先を変更できます。おすすめに5枠表示します。</p><form id="category-quick-links-form">${['offers'].map(key=>`<section class="quick-links-tab-card"><h3>${key==='offers'?'おすすめ':key==='high'?'ガポガポ':'すぐできる'}</h3><div class="tbl"><table><thead><tr><th>表示名</th><th>画像</th><th>遷移先種別</th><th>遷移先</th></tr></thead><tbody>${categoryQuickLinks(state,key).map((item,i)=>`<tr data-quick-key="${key}" data-quick-index="${i}"><td><input name="label" value="${esc(item.label)}" maxlength="20" required></td><td><input name="image" value="${esc(item.image||'')}" placeholder="画像URL（任意）"><input type="file" data-quick-image accept="image/png,image/jpeg,image/webp"><small class="tiny">正方形画像。未設定時は名称の簡易ロゴ</small></td><td>${quickLinkDestinationFields(item)}</td><td><span class="quick-link-id">${esc(item.id)}</span></td></tr>`).join('')}</tbody></table></div></section>`).join('')}<div class="actions"><button class="btn primary" type="submit">変更を保存</button><span class="err" role="alert"></span></div></form><div class="note spec">モックの初期表示は、楽天／PayPay／Vポイント／dポイント／Pontaです。遷移先の実案件・URLは運用時に設定します。</div></section><style>.quick-links-tab-card{margin:22px 0;padding:18px;background:#fbfdfc;border:1px solid #dce7e1;border-radius:12px}.quick-links-tab-card h3{margin-top:0}.quick-links-tab-card table{min-width:900px}.quick-links-tab-card input,.quick-links-tab-card select{width:100%;box-sizing:border-box}.quick-links-tab-card input[type=file]{margin-top:7px}.quick-links-tab-card td{vertical-align:top}.quick-link-id{font-family:monospace;color:#74867c}.quick-links-admin .tbl{overflow:auto}</style></section>`;}
function missionsPage(){const group=dailyMissionGroups(state)[0];return `<section class="panel daily-admin"><form id="daily-links-form" novalidate><div id="daily-groups">${dailyGroupEditor(group)}</div><div class="actions"><button class="btn primary" type="submit">変更を保存</button><span class="err" role="alert"></span></div></form></section>`;}




function refreshMissionSummary(){const f=document.querySelector('#mission-config-form');if(!f)return;const rows=[...f.querySelectorAll('[data-task-id]')].filter(r=>r.querySelector('[name=enabled]').checked);f.querySelector('[data-mission-summary]').textContent=`有効 ${rows.length}件 ／ 報酬合計 ${rows.reduce((sum,r)=>sum+Number(r.querySelector('[name=reward]').value),0)}pt`;f.dataset.dirty='1';}
// ===== アンケート還元率 =====
function surveyPage(){const R={...state.limits.surveyRate,monitor:100};return `<section class="panel"><h2>ライフサーベイのユーザー還元率</h2><p class="desc">ライフサーベイの基準ポイントに対して、ユーザーへの還元率を設定します。デモグラは100pt／回固定です。</p>
<div class="tbl"><table><thead><tr><th>アンケート種別</th><th>100%還元時</th><th>ユーザー還元率</th><th>ユーザー還元</th><th></th></tr></thead><tbody>${[['main','本調査',500],['screening','スクリーニング',50],['monitor','デモグラ',100]].map(([k,n,base])=>`<tr data-survey-rate-row data-unit="${k==='monitor'?'回':'問'}" data-base="${base??''}"><td>${n}${k==='monitor'?'（固定・変更不可）':''}</td><td>${base===null?'未定':pt(base)+'pt／'+(k==='monitor'?'回':'問')}</td><td><label class="inline-edit"><input aria-label="${n}のユーザー還元率" type="number" min="0" step="1" style="${R[k]>100?'color:#b42318;border-color:#b42318':''}" value="${R[k]}" data-rate="${k}" ${k==='monitor'?'disabled':''}> %</label></td><td><strong data-rate-preview style="${R[k]>100?'color:#b42318':''}">${base===null?'単価未設定':pt(base*R[k]/100)+'pt／'+(k==='monitor'?'回':'問')}</strong><div data-rate-warning role="status" style="color:#b42318;font-size:12px">${R[k]>100?'100%を超えています。ユーザーへの還元が基準ポイントを上回ります。':''}</div></td><td><button class="btn sm" data-action="save-rate" data-id="${k}" ${k==='monitor'?'disabled':''}>保存</button></td></tr>`).join('')}</tbody></table></div><p class="tiny">基準ポイントは固定です。</p><p class="desc">本調査・スクリーニング：回答した設問数 × 基準ポイント／問 × ユーザー還元率 ÷ 100<br>デモグラ：1回の回答完了につき100pt固定（設問数・還元率による変更なし）</p></section><section class="panel"><h2>種別ごとの表示セクション <span class="tag">Tier2</span></h2><p class="desc">表示セクションの追加・削除はTier2で対応予定です。</p></section>`;}
document.addEventListener('input',e=>{if(!e.target.matches('[data-rate]'))return;const input=e.target,row=input.closest('[data-survey-rate-row]');if(!row)return;const value=Number(input.value),invalid=input.value.trim()===''||!Number.isFinite(value)||value<0||!Number.isInteger(value),over=value>100;const preview=row.querySelector('[data-rate-preview]');preview.textContent=invalid?'—':(Number(row.dataset.base)*value/100).toLocaleString('ja-JP',{maximumFractionDigits:2})+'pt／'+row.dataset.unit;preview.style.color=input.style.color=over||invalid?'#b42318':'';input.style.borderColor=over||invalid?'#b42318':'';input.setAttribute('aria-invalid',String(invalid));row.querySelector('[data-rate-warning]').textContent=invalid?'0以上の整数を入力してください。':over?'100%を超えています。ユーザーへの還元が基準ポイントを上回ります。':'';row.querySelector('[data-action="save-rate"]').disabled=invalid;});

function surveyRatePage(){const R=state.limits.surveyRate;R.rpn??={screening:100,main:100};const names={monitor:'モニタ情報取得',screening:'スクリーニング',main:'本調査'};const lifeRows=Object.entries(names).map(([k,n])=>{const ex=surveys.find(q=>q.type===k);return `<tr><td>${n}</td><td class="num"><span class="inline-edit"><input type="number" min="0" max="100" value="${R[k]}" data-rate="${k}"> %</span></td><td class="tiny">${ex?`${esc(ex.title)}：${ex.rewardYen}円 → ${pt(surveyReward(state,ex))}pt`:'100円 → '+pt(Math.round(100*R[k]/100*100))+'pt'}</td><td><button class="btn sm" data-action="save-rate" data-id="${k}">保存</button></td></tr>`}).join('');const rpnRows=[['screening','スクリーニング（10問）',110,'基準：10問ごとに110pt'],['main','本調査（1問）',110,'基準：1問あたり110pt']].map(([k,n,base,example])=>`<tr><td>${n}</td><td class="num"><span class="inline-edit"><input type="number" min="0" max="100" value="${R.rpn[k]}" data-rate="rpn-${k}"> %</span></td><td class="tiny">${example} → ${pt(Math.round(base*R.rpn[k]/100))}pt（還元率${R.rpn[k]}%）</td><td><button class="btn sm" data-action="save-rate" data-id="rpn-${k}">保存</button></td></tr>`).join('');return `<section class="panel"><h2>LIFE Surveyのユーザー還元率 ${badge('spec')} <span class="tiny">spec: admin/survey-redemption-rate.md</span></h2><p class="desc">LIFE Surveyの報酬額に対するユーザー還元率を設定します。表示は取得時点、付与は回答完了時点の率で反映します。</p><div class="tbl"><table class="survey-rate-table"><thead><tr><th>種別</th><th class="num">還元率</th><th>換算例</th><th></th></tr></thead><tbody>${lifeRows}</tbody></table></div><div class="note spec">LIFE Surveyの基準ポイントは固定です。デモグラは100pt／回固定で、還元率は変更できません。</div></section><section class="panel"><h2>リサーチプラスネットワークのユーザー還元率</h2><p class="desc">リサーチプラスネットワークの報酬額を100%還元時の基準として、ユーザーへの還元率を設定します。LIFE Surveyとは別に管理します。</p><div class="tbl"><table class="survey-rate-table"><thead><tr><th>種別</th><th class="num">還元率</th><th>換算例</th><th></th></tr></thead><tbody>${rpnRows}</tbody></table></div><div class="note spec">SCRは10問ごとに110pt、本調査は1問あたり110ptが100%還元時の基準です。</div></section>`;}

// ===== 審査・交換上限 =====
function reviewPage(){const pend=state.user.pendings;const cap=L(state).exchangeDailyCap;const used=state.exchangeUsedToday;return `<section class="panel"><h2>付与予定の審査 ${badge('spec')} <span class="tiny">spec: admin/point-grant-review.md / jobs/point-auto-review.md</span></h2><p class="desc">付与予定（準備中）のうち、自動判定の対象（歩数・動画・デイリーミッション・アンケート）はジョブが確定し、案件（定額・定率）は運用者の有人審査で確定する。詰まった付与予定は手動で確定・取り消しできる。取り消しはユーザーに通知しない。</p>
<div class="toolbar"><button class="btn primary" data-action="run-auto">ポイント自動判定を実行（${pend.filter(x=>x.review==='auto').length}件）</button><button class="btn" data-action="approve-all-manual">有人審査を一括承認（${pend.filter(x=>x.review==='manual').length}件）</button></div>
<div class="tbl"><table><thead><tr><th>登録日</th><th>タイトル</th><th>説明</th><th>カテゴリ</th><th class="num">pt</th><th>確定経路</th><th>操作</th></tr></thead><tbody>${pend.slice().reverse().map(p=>`<tr><td>${p.date}</td><td>${esc(p.title)}</td><td class="tiny">${esc(p.desc)}</td><td><code>${p.category}</code></td><td class="num">${pt(p.amount)}</td><td>${p.review==='manual'?badge('warn','有人審査'):badge('on','自動判定')}</td><td class="ops"><button class="btn sm" data-action="approve-pending" data-id="${p.id}">承認</button> <button class="btn sm danger" data-action="reject-pending" data-id="${p.id}">却下</button></td></tr>`).join('')||'<tr><td colspan="7" class="tiny">審査待ちはありません</td></tr>'}</tbody></table></div></section>
<section class="panel"><h2>日次交換総額上限 ${badge('spec')} <span class="tiny">spec: admin/dotmoney-exchange-cap.md</span></h2><p class="desc">サービス全体で 1 日（JST）に交換できるポイントの総量。到達後はその日の全ユーザーの交換が成立しない。未設定は上限 0 と同じ扱い。</p><div class="tiny">本日の利用 ${pt(used)} / ${pt(cap)} pt（${Math.round(used/cap*100)}%）</div><div class="meter ${used>=cap?'over':''}"><i style="width:${Math.min(100,used/cap*100)}%"></i></div><form class="grid" id="cap-form"><label>上限（pt）<input type="number" name="cap" value="${cap}" min="0"></label><div class="actions"><button class="btn primary" type="submit">保存</button><span class="err">${esc(formError)}</span></div></form></section>`;}

// ===== 成果・解禁 =====
function casesPage(){const st={challenging:'挑戦中',judging:'判定中',approved:'承認',rejected:'否認'};return `<section class="panel"><h2>案件の成果（NACS からの通知の再現） ${badge('ext')}</h2><p class="desc">成果の発生・承認・否認は NACS が正で、タメルコの運用者は変更できない。ここでは NACS からの通知を再現して、マイ案件の成果ステータスと付与予定の登録（承認 → 有人審査待ち）を確認する。成果の発生・通知の停止・再送などは <a href="../mock-nacs/#conversions" target="_blank">NACS モック ↗</a> で操作できる。</p>
<div class="tbl"><table><thead><tr><th>案件</th><th>成果 ID</th><th>ステータス</th><th>日時</th><th class="num">報酬</th><th>SUR 段階</th><th>操作</th></tr></thead><tbody>${state.user.cases.slice().reverse().map(c=>{const o=offersOf(state).find(x=>x.id===c.offerId);const open=['challenging','judging'].includes(c.status);return `<tr class="${open?'':'dim'}"><td>${esc(c.name)}</td><td class="tiny">${c.id.slice(0,8)}</td><td>${badge(c.status==='approved'?'on':c.status==='rejected'?'danger':'warn',st[c.status])}</td><td class="tiny">${c.date}</td><td class="num">${c.rewardMode==='rate'?c.reward+'%':pt(c.reward)+'pt'}</td><td>${o?.sur?`${c.paidStages}/${o.sur.length}`:'—'}</td><td class="ops">${open?`<button class="btn sm" data-action="approve-case" data-id="${c.offerId}">承認${o?.sur?'（1 段階）':''}</button> <button class="btn sm danger" data-action="reject-case" data-id="${c.offerId}">否認</button>`:''}</td></tr>`;}).join('')||'<tr><td colspan="7" class="tiny">成果はありません。アプリで案件に「チャレンジ」すると発生します</td></tr>'}</tbody></table></div></section>
<section class="panel"><h2>インストール案件の解禁 ${badge('spec')} <span class="tiny">spec: admin/install-affiliate-unlock.md</span></h2><p class="desc">同じ日に動画リワードの視聴成立を 5 件記録したユーザーは自動で解禁される。運用者は個別に解禁・再ロックできる。解禁は一覧の絞り込みにだけ効き、詳細の直接表示は妨げない。</p><p>デモ利用者：${state.user.installUnlocked?badge('on','解禁済み'):badge('off','未解禁')} <button class="btn sm" data-action="toggle-install">${state.user.installUnlocked?'再ロックする':'解禁する'}</button></p></section>
<section class="panel"><h2>デモ利用者の状態</h2><p class="tiny">確認日 ${state.date}／利用者区分 ${state.persona}／歩数連携 ${state.stepLink}／SMS 本人確認 ${state.user.sms?'済み':'未'}／本日の動画 ${day(state).video}回・歩数マイルストーン ${day(state).stepsClaimed}回。利用者側の切り替えはアプリモックの「デモ設定」で行う。</p></section>`;}

// ===== 実績 =====
function metricsPage(){const m=state.metrics;const byStatus=['challenging','judging','approved','rejected'].map(k=>[k,state.user.cases.filter(c=>c.status===k).length]);return `<section class="panel"><h2>実績 ${badge('new')}</h2><p class="desc">運用枠ごとの表示（imp）・タップ（tap）・成果（cv）、案件の成果ステータス、アンケートの開始・完了。現行仕様では行動ログ（lydia-log-constants）と Braze 側の計測に分かれており、運用画面での集計は新規。CV は承認成果を数え、開始クリックと混同しない。</p><div class="toolbar"><span class="grow"></span><button class="btn" data-action="csv">CSV を保存</button></div>
<div class="two"><div><h3>運用枠</h3><div class="tbl"><table><thead><tr><th>枠</th><th class="num">imp</th><th class="num">tap</th><th class="num">cv</th><th class="num">tap率</th></tr></thead><tbody>${state.slots.map(s=>{const x=m[s.id]||{imp:0,tap:0,cv:0};return `<tr><td>${esc(s.name)}</td><td class="num">${x.imp}</td><td class="num">${x.tap}</td><td class="num">${x.cv}</td><td class="num">${x.imp?Math.round(x.tap/x.imp*100)+'%':'—'}</td></tr>`;}).join('')}</tbody></table></div></div>
<div><h3>案件の成果ステータス</h3><div class="tbl"><table><tbody>${byStatus.map(([k,n])=>`<tr><td>${({challenging:'挑戦中',judging:'判定中',approved:'承認',rejected:'否認'})[k]}</td><td class="num">${n}</td></tr>`).join('')}</tbody></table></div><h3>アンケート</h3><div class="tbl"><table><tbody><tr><td>回答開始</td><td class="num">${state.surveyStarts.length}</td></tr><tr><td>回答完了</td><td class="num">${state.surveyCompletions.length}</td></tr><tr><td>完了率</td><td class="num">${state.surveyStarts.length?Math.round(state.surveyCompletions.length/state.surveyStarts.length*100)+'%':'—'}</td></tr></tbody></table></div><h3>チャレンジボーナス</h3><div class="tbl"><table><tbody>${challengeSlots(state).map(c=>`<tr><td>${esc(c.name)}</td><td class="num">${c.participants.toLocaleString()} / ${c.challengeGoal.toLocaleString()}人 ${challengeAchieved(c)?badge('on','達成'):''}</td></tr>`).join('')}</tbody></table></div></div></div></section>`;}
function logsPage(){return `<section class="panel"><h2>変更ログ</h2><p class="desc">管理画面の変更系操作を、実行日時・操作者・操作・内容で記録する（spec：変更系 API へのアクセスは操作ログとして記録。設定単位の操作者名は記録されない）。</p><div class="tbl"><table><thead><tr><th>日時</th><th>操作者</th><th>操作</th><th>内容</th></tr></thead><tbody>${state.logs.map(l=>`<tr><td class="tiny">${l.at.slice(0,19).replace('T',' ')}</td><td>${esc(l.actor)}</td><td>${esc(l.label)}</td><td class="log-details" title="${esc(l.details)}">${esc(l.details)}</td></tr>`).join('')||'<tr><td colspan="4" class="tiny">ログはありません</td></tr>'}</tbody></table></div></section>`;}

// ===== 描画 =====
const pages={'side-tabs':['おすすめサイドタブ',sideTabsPage],'receipt-options':['レシート販促オプション',optionAdmin],receipts:['レシート掲載管理',receiptAdmin],dashboard:['ダッシュボード',dashboard],'top-menu':['TOP画面上部のメニュー',topMenuPage],challenges:['チャレンジボーナス',slotsPage],banners:['バナー&テキスト広告',slotsPage],campaigns:['キャンペーンページ',featuresPage],'text-ads':['オトク内テキスト広告',slotsPage],chinchiro:['チンチロ',chinchiroPage],screens:['案件画面設定',screensPage],points:['付与設定',pointsPage],missions:['デイリーミッション設定',missionsPage],survey:['アンケート還元率',surveyRatePage],review:['審査・交換上限',reviewPage],cases:['成果・解禁',casesPage],metrics:['実績',metricsPage],logs:['変更ログ',logsPage]};
pages['tametoku-order']=['お得タブ表示設定',tametokuOrderPage];
pages['high-reward']=['高還元タブの掲載設定',()=>highRewardEditor(state,validHighRewardMonth(location.hash.split('/')[1])?location.hash.split('/')[1]:state.date.slice(0,7))];
pages['quick-links']=['お得タブサービス名リンク',quickLinksPage];
function render(){const [title,fn]=pages[route()]||pages.dashboard;document.title=`${title} | 全ポイ活アプリ管理画面`;root.innerHTML=shell(title,fn());}
function updated(msg){save();render();if(msg)toast(msg);}
function showModal(title,body){modal.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="btn sm" data-action="close">閉じる</button></div><div class="modal-body">${body}</div>`;if(!modal.open)modal.showModal();}
function readSlotForm(f,preview=false){if(f.dataset.section==='banner')return readCarouselForm(state,f,state.slots.find(x=>x.id===f.dataset.id)||editingSlot||{},preview);const fd=new FormData(f),old=state.slots.find(x=>x.id===f.dataset.id)||editingSlot||{},section=f.dataset.section;const resolved=['banner','text'].includes(section)?resolveBannerLink(state,fd.get('to'),location.href):null;return {...old,id:f.dataset.id,name:fd.get('name').trim(),kind:section==='text'?'ticker':section==='challenge'?'challenge':fd.get('kind'),destination:resolved?(old.kind==='challenge'?old.destination:resolved.destination):fd.get('destination'),placements:fd.getAll('placements'),enabled:fd.get('enabled')==='1',start:fd.get('start'),end:fd.get('end'),segment:fd.get('segment'),priority:Number(fd.get('priority')),title:section==='text'?fd.get('title').trim():old.title||fd.get('name').trim(),text:old.text||'',bannerImage:section==='text'?'':fd.get('bannerImage')??old.bannerImage??'',rewardMode:old.rewardMode||'flat',reward:old.reward||0,to:resolved?resolved.to:section==='challenge'?old.to:fd.get('to').trim(),tab:fd.get('tab')||old.tab,position:fd.get('position')||old.position||'top',...(section==='challenge'?{challengeGoal:Number(fd.get('challengeGoal')),participants:Number(fd.get('participants')),bonus:Number(fd.get('bonus'))}:{})};}

function readSettingForm(f){const fd=new FormData(f);const rows=[...f.querySelectorAll('#group-rows tbody tr')];return {id:f.dataset.id,applyAt:fd.get('applyAt'),memo:fd.get('memo').trim(),groups:rows.map((tr,i)=>({id:tr.dataset.gid,name:tr.querySelector('[name=g-name]').value.trim(),category:tr.querySelector('[name=g-category]').value,...(f.dataset.code==='home_tabs'?{menuCategory:tr.querySelector('[name=g-menu-category]').value}:{}),listCode:tr.querySelector('[name=g-list]')?.value||undefined,icon:tr.querySelector('[name=g-icon]').value,iconImage:tr.querySelector('[data-icon-value]')?.value||'',unit:tr.querySelector('[name=g-unit]').value,order:Number(tr.querySelector('[name=g-order]').value)||i+1,tags:tr.querySelector('[name=g-tags]').checked}))};}
function csv(){const rows=[['slot','name','kind','imp','tap','cv'],...state.slots.map(s=>{const x=state.metrics[s.id]||{imp:0,tap:0,cv:0};return [s.id,s.name,s.kind,x.imp,x.tap,x.cv];})];const text=rows.map(r=>r.map(v=>`"${String(v).replaceAll('"','""')}"`).join(',')).join('\n');const u=URL.createObjectURL(new Blob(['﻿'+text],{type:'text/csv'}));const a=document.createElement('a');a.href=u;a.download=`tameruko-metrics-${state.date}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}

document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;formError='';
 try{switch(a){
 case'daily-add-mission':{const g=el.closest('[data-daily-group]');const id=g.querySelector('[name=add-source]').value;if(!id)break;if([...g.querySelectorAll('[data-daily-id]')].some(x=>x.dataset.dailyId===id)){toast('このミッションは追加済みです');break;}const q=surveys.find(x=>'survey-'+x.id===id);const holder=document.createElement('div');holder.innerHTML=dailyGroupEditor({id:'temp',name:'',missions:[{id,title:q.title,sub:'回答完了でポイント獲得',to:'answer/'+q.id,enabled:true}]});g.querySelector('.daily-group-missions').append(holder.querySelector('[data-daily-id]'));break;}
 case'daily-remove-mission':el.closest('[data-daily-id]').remove();break;
 case'daily-mission-up':{const row=el.closest('[data-daily-id]');if(row.previousElementSibling)row.parentNode.insertBefore(row,row.previousElementSibling);break;}
 case'daily-mission-down':{const row=el.closest('[data-daily-id]');if(row.nextElementSibling)row.parentNode.insertBefore(row.nextElementSibling,row);break;}

 case'preview-feature-draft':{const form=document.querySelector('#feature-form');if(form.dataset.uploading)throw Error('画像の読み込み完了をお待ちください');const fd=new FormData(form),tags=fd.getAll('bundleTags'),feature={id:fd.get('id'),title:fd.get('title')||'キャンペーン',lead:'',kind:'collection',imageOnly:true,blocks:[],start:'',end:'',displayLimit:Number.MAX_SAFE_INTEGER,bannerImage:fd.get('bannerImage')||'',offerIds:[...new Set((state.nacs?.intake?.bundles||[]).filter(b=>(b.tags||[]).some(t=>tags.includes(t))).map(b=>b.id).filter(id=>offersOf(state).some(o=>o.id===id)))]};const url=new URL('../mock-app/',location.href);url.searchParams.set('bannerPreview','1');url.hash='feature/'+feature.id;const win=window.open(url.href,'_blank');if(!win)throw Error('ポップアップがブロックされています。');const snapshot=structuredClone(state);let tries=0;const timer=setInterval(()=>{if(win.closed||tries++>50){clearInterval(timer);return;}try{if(win.document.readyState==='complete'&&win.location.href===url.href){win.postMessage({type:'campaign-preview',state:snapshot,feature},location.origin);clearInterval(timer);}}catch{}},100);break;}


 case'edit-campaign-banner':editingCampaignBanner=id;editingSlot=null;render();break;
 case'close-campaign-banner':editingCampaignBanner=null;render();break;
 case'move-challenge':moveChallenge(state,id,Number(el.dataset.dir));updated('チャレンジボーナスの並び順を保存しました。');break;
 case'add-browse-mission':document.querySelector('#mission-editor-rows').insertAdjacentHTML('beforeend',missionEditorRow({id:'browse-'+crypto.randomUUID().slice(0,8),type:'VIEW_OFFER',title:'案件の詳細ページを見てみよう',sub:'対象案件の詳細ページを開いたらクリア',offerId:'',reward:100,enabled:true,extra:true}));refreshMissionSummary();break;
 case'remove-browse-mission':el.closest('tr').remove();refreshMissionSummary();break;
 case'reload':load();render();toast('アプリの状態を読み込みました。');break;
 case'close':modal.close();break;
 // 運用枠
 case'new-slot':editingSlot=null;editingSlot=undefined;render();break;
 case'edit-slot':editingSlot=state.slots.find(x=>x.id===id);render();break;
 case'dup-slot':{const src=state.slots.find(x=>x.id===id);editingSlot={...structuredClone(src),id:'slot-'+crypto.randomUUID().slice(0,8),name:src.name+'（複製）',copyDraft:true,displayOrder:undefined,enabled:false};render();break;}
 case'cancel-slot':editingSlot=null;render();break;
 case'toggle-slot':{const s=state.slots.find(x=>x.id===id);s.enabled=!s.enabled;audit(state,`枠を${s.enabled?'再開':'停止'}：${s.name}`,'');updated(`${s.name} を${s.enabled?'再開':'停止'}しました。アプリの次回表示から反映されます。`);break;}
 case'del-slot':{const s=state.slots.find(x=>x.id===id);if(confirm(`「${s.name}」を削除します。元に戻せません。`)){removeSlot(state,id);updated('枠を削除しました。');}break;}
 // 特集
 case'new-feature':editingFeature=undefined;render();break;
 case'edit-feature':editingFeature=state.features.find(x=>x.id===id);render();break;
 case'cancel-feature':editingFeature=null;render();break;
 case'del-feature':{const used=state.slots.filter(x=>x.to===`feature/${id}`);if(used.length){toast(`この特集は枠「${used[0].name}」のリンク先です。先に枠のリンク先を変えてください。`);break;}if(confirm('この特集を削除します。')){removeFeature(state,id);updated('特集を削除しました。');}break;}
 // 案件画面設定
 case'screen-code':screenCode=el.dataset.code;editingSetting=null;render();break;
 case'new-screen':{const code=prompt('画面コード（アプリが FetchAffiliateGroups に渡す文字列）');if(!code)break;if(state.screens[code]){toast('同じ画面コードがあります。');break;}state.screens[code]={memo:prompt('メモ')||'',settings:[]};audit(state,`画面を作成：${code}`,'');screenCode=code;updated('画面コードを作成しました。設定を持たないため、アプリからは 0 件が返ります。');break;}
 case'new-setting':editingSetting=undefined;render();break;
 case'edit-setting':editingSetting=state.screens[screenCode].settings.find(x=>x.id===id);render();break;
 case'cancel-setting':editingSetting=null;render();break;
 case'del-setting':if(confirm('この設定を削除します。適用中の設定を削除すると直前の過去の設定に戻ります。')){deleteScreenSetting(state,screenCode,id);updated('設定を削除しました。');}break;
 case'add-group-row':{const tb=document.querySelector('#group-rows tbody');const gid='g-'+Date.now().toString(36);tb.insertAdjacentHTML('beforeend',`<tr data-gid="${gid}"><td><input name="g-name"></td>${screenCode==='home_tabs'?menuCategoryCell({category:'daily'}):''}<td><select name="g-category" aria-label="表示する内容">${(screenCode==='home_tabs'?['daily']:['すべて','買い物','旅行','ゲーム','アプリ','金融','challenges','surveys','mycases']).map(c=>`<option value="${c}">${screenCode==='home_tabs'?(tabName[c]||c).replace('ホーム：',''):c}</option>`).join('')}</select></td><td>${listSelect('')}</td><td><select name="g-icon">${['cart','plane','game','phone','yen','gift','spark','bag','survey','walk','wallet','calendar','chat'].map(c=>`<option>${c}</option>`).join('')}</select>${iconUpload('')}</td><td><select name="g-unit"><option value="jpy">円</option><option value="point">pt</option></select></td><td><input type="number" name="g-order" value="${tb.children.length+1}" style="width:60px"></td><td><input type="checkbox" name="g-tags" checked></td><td><button class="btn sm danger" type="button" data-action="del-group-row">削除</button></td></tr>`);break;}
 case'del-group-row':el.closest('tr').remove();break;
 // 付与設定
 case'del-reservation':deleteReservation(state,id);updated('予約を削除しました。');break;
 // ミッション
 case'save-mission':{const v=Number(document.querySelector(`input[data-mission="${id}"]`).value);setMissionReward(state,id,v);updated('報酬を変更しました。即時に反映されます。');break;}
 case'toggle-mission':{const m=state.missionDef.find(x=>x.id===id);setMissionEnabled(state,id,!m.enabled);updated(`タスクを${m.enabled?'有効':'無効'}にしました。`);break;}
 // 還元率
 case'save-rate':{const v=Number(document.querySelector(`input[data-rate="${id}"]`).value);if(id.startsWith('rpn-')){const type=id.slice(4);if(!['screening','main'].includes(type))throw Error('リサーチプラスネットワークの種別が不正です。');if(!Number.isSafeInteger(v)||v<0||v>100)throw Error('還元率は0〜100の整数で入力してください。');state.limits.surveyRate.rpn??={screening:100,main:100};const before=state.limits.surveyRate.rpn[type];state.limits.surveyRate.rpn[type]=v;audit(state,`リサーチプラスネットワーク還元率を変更：${type}`,`${before}% → ${v}%`);}else{if(v>100&&!window.confirm('還元率が100%を超えています。ユーザーへの還元が基準ポイントを上回ります。この内容で保存しますか？'))break;setSurveyRate(state,id,v);}updated('還元率を変更しました。一覧の表示と以降の付与に反映されます。');break;}
 // 審査
 case'run-auto':{const n=autoReview(state);updated(`ポイント自動判定を実行し、${n}件を確定しました。`);break;}
 case'approve-all-manual':{const n=manualReview(state);updated(`有人審査で${n}件を承認しました。`);break;}
 case'approve-pending':reviewPending(state,id,true);updated('承認しました。保有ポイントに移りました。');break;
 case'reject-pending':if(confirm('この付与予定を却下（取り消し）します。ユーザーには通知されません。')){reviewPending(state,id,false);updated('却下しました。');}break;
 // 成果
 case'approve-case':progressOffer(state,id);updated('NACS の成果承認を再現しました。付与予定（有人審査）に登録されます。');break;
 case'reject-case':rejectOffer(state,id);updated('NACS の成果否認を再現しました。');break;
 case'toggle-noloss':state.showNoLoss=!(state.showNoLoss!==false);audit(state,`目減りゼロ表示を${state.showNoLoss?'ON':'OFF'}`,'');updated(state.showNoLoss?'目減りゼロ表示をONにしました。':'目減りゼロ表示をOFFにしました。');break;
 case'toggle-install':state.user.installUnlocked=!state.user.installUnlocked;audit(state,`インストール案件を${state.user.installUnlocked?'解禁':'再ロック'}`,'デモ利用者');updated(state.user.installUnlocked?'解禁しました。':'再ロックしました。同日に動画を5回視聴すると再度解禁されます。');break;
 case'csv':csv();toast('CSV を保存しました。');break;
 }}catch(err){formError=err.message;render();toast(err.message);}
});
