document.addEventListener('submit',e=>{if(e.target.id!=='category-quick-links-form')return;e.preventDefault();const f=e.target;try{if(f.dataset.quickUploading)throw Error('画像の読み込み完了をお待ちください。');const next={...state.categoryQuickLinks};for(const key of ['offers']){next[key]=[...f.querySelectorAll(`[data-quick-key="${key}"]`)].map(row=>{const label=row.querySelector('[name=label]').value.trim(),type=row.querySelector('[name=destinationType]').value,destination=row.querySelector('[name=destination]').value.trim(),image=row.querySelector('[name=image]').value.trim();if(!label||label.length>20)throw Error('表示名は1〜20文字で入力してください。');if(!['affiliate-list','offer-detail','custom-url'].includes(type))throw Error('遷移先種別が不正です。');if(type==='affiliate-list'&&!destination)throw Error('バンドル属性名を入力してください。');if(type==='offer-detail'&&!offersOf(state).some(o=>o.id===destination))throw Error('案件詳細の案件IDが見つかりません。');if(type==='custom-url'&&!/^(https?:\/\/|#[a-z])/i.test(destination))throw Error('設定したURLは https://、http:// またはアプリ内の # で入力してください。');return{...categoryQuickLinks(state,key)[Number(row.dataset.quickIndex)],label,destinationType:type,destination,bundleAttribute:type==='affiliate-list'?destination:undefined,image};});}state.categoryQuickLinks=next;audit(state,'お得タブサービス名リンクを更新','おすすめ／ガポガポ／すぐできる 各5枠');updated('お得タブのサービス名リンクを保存しました。');}catch(err){const out=f.querySelector('.err');if(out)out.textContent=err.message;toast(err.message);}});
