function iconUpload(value){return `<div class="icon-upload"><label class="btn sm">アイコンをアップロード<input type="file" data-icon-file accept="image/png,image/jpeg,image/webp" style="display:none"></label><input type="hidden" data-icon-value value="${esc(value)}"><img data-icon-preview ${value?`src="${esc(value)}"`:'hidden'} alt="アイコンプレビュー" style="width:40px;height:40px;object-fit:contain"><button type="button" class="btn sm" data-icon-reset>既定に戻す</button><small>正方形・2MB以下</small><span data-icon-error class="err" role="alert"></span></div>`;}
document.addEventListener('change',async e=>{if(!e.target.matches('[data-icon-file]'))return;const box=e.target.closest('.icon-upload'),form=e.target.closest('form');form.dataset.iconUploading=String(Number(form.dataset.iconUploading||0)+1);try{const url=await readImage(e.target.files[0]);const img=new Image();img.src=url;await img.decode();if(img.naturalWidth!==img.naturalHeight)throw Error('正方形の画像を選んでください');box.querySelector('[data-icon-value]').value=url;box.querySelector('[data-icon-preview]').src=url;box.querySelector('[data-icon-preview]').hidden=false;box.querySelector('[data-icon-error]').textContent='';}catch(err){box.querySelector('[data-icon-error]').textContent=err.message;}finally{form.dataset.iconUploading=String(Number(form.dataset.iconUploading)-1);}});
