let draggingBanner=null;
function moveBannerBefore(id,target){const rows=[...document.querySelectorAll('[data-order-id]')],ids=rows.map(r=>r.dataset.orderId);if(id===target||!ids.includes(id)||!ids.includes(target))return;const targetIndex=ids.indexOf(target);ids.splice(ids.indexOf(id),1);ids.splice(targetIndex,0,id);reorderBannerRecords(state,ids);save();render();toast('表示順を保存しました。');}
document.addEventListener('dragstart',e=>{const h=e.target.closest('[data-drag-banner]');if(!h)return;draggingBanner=h.dataset.dragBanner;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',draggingBanner);});
document.addEventListener('dragover',e=>{if(draggingBanner&&e.target.closest('[data-order-id]')){e.preventDefault();e.dataTransfer.dropEffect='move';}});
document.addEventListener('drop',e=>{const row=e.target.closest('[data-order-id]');if(!draggingBanner||!row)return;e.preventDefault();moveBannerBefore(draggingBanner,row.dataset.orderId);draggingBanner=null;});
document.addEventListener('dragend',()=>draggingBanner=null);
document.addEventListener('keydown',e=>{const h=e.target.closest('[data-drag-banner]');if(!h||!['ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const ids=[...document.querySelectorAll('[data-order-id]')].map(r=>r.dataset.orderId),i=ids.indexOf(h.dataset.dragBanner),j=i+(e.key==='ArrowUp'?-1:1);if(j<0||j>=ids.length)return;[ids[i],ids[j]]=[ids[j],ids[i]];reorderBannerRecords(state,ids);save();render();document.querySelector(`[data-drag-banner="${h.dataset.dragBanner}"]`)?.focus();toast('表示順を保存しました。');});
// ポインター操作でも並べ替え（タッチ端末を含む）。
let bannerPointer=null;
document.addEventListener('pointerdown',e=>{const h=e.target.closest('[data-drag-banner]');if(h){bannerPointer={id:h.dataset.dragBanner,y:e.clientY};}});
document.addEventListener('pointerup',e=>{if(!bannerPointer)return;const source=bannerPointer;bannerPointer=null;if(Math.abs(e.clientY-source.y)<8)return;const row=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-order-id]');if(row)moveBannerBefore(source.id,row.dataset.orderId);});
document.addEventListener('pointercancel',()=>bannerPointer=null);

